<script setup>
import { ref,reactive,onMounted,computed } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { api } from '../../services/api.js';
import { notify } from '../../services/notifications.js';
import { fetchAll,idOf,shortDate } from '../../services/panel.js';
import Icon from '../../components/Icon.vue';
const route=useRoute(),router=useRouter(),editing=computed(()=>Boolean(route.params.id));
let createdId='';
const loading=ref(true),saving=ref(false),renewing=ref(false),error=ref(''),plans=ref([]),user=ref(null);
const form=reactive({name:'',email:'',active:true}),assignment=reactive({planId:'',days:30});
onMounted(async()=>{try{plans.value=await fetchAll('/admin/plans');if(editing.value){user.value=await api.get(`/admin/users/${route.params.id}`);Object.assign(form,{name:user.value.name,email:user.value.email,active:user.value.active});assignment.planId=idOf(user.value.planId);assignment.days=plans.value.find(p=>p._id===assignment.planId)?.durationDays||30;}}catch(e){error.value=e.message}finally{loading.value=false}});
async function save(){saving.value=true;error.value='';try{const data=(editing.value||createdId)?await api.put(`/admin/users/${route.params.id||createdId}`,form):await api.post('/admin/users',form);if(!editing.value)createdId=data._id;if(!editing.value&&assignment.planId)await api.put(`/admin/users/${data._id}/plan`,assignment);notify.success(editing.value?'Vendedor actualizado.':'Vendedor creado. Podrá ingresar con un enlace a su correo.');await router.push('/app/users')}catch(e){error.value=e.message;notify.error(e.message)}finally{saving.value=false}}
async function renew(){if(!assignment.planId)return;renewing.value=true;try{await api.put(`/admin/users/${route.params.id}/plan`,assignment);user.value=await api.get(`/admin/users/${route.params.id}`);notify.success('Plan asignado o renovado correctamente.')}catch(e){notify.error(e.message)}finally{renewing.value=false}}
function choosePlan(){assignment.days=plans.value.find(p=>p._id===assignment.planId)?.durationDays||30;}
</script>
<template><div><RouterLink to="/app/users" class="p-back-link"><Icon name="back" :size="14"/>Volver a usuarios</RouterLink><header class="p-page-header"><div><h1>{{editing?'Gestionar vendedor':'Nuevo vendedor'}}</h1><p>{{editing?'Actualizá los datos y acompañá el crecimiento de su negocio.':'Solo necesita un correo para empezar. No se genera una contraseña.'}}</p></div></header><div v-if="error" class="p-error">{{error}}</div><div v-if="loading" class="p-loading-page"><span class="p-spinner"/></div><form v-else @submit.prevent="save" class="p-form"><section class="p-section-card"><div class="p-section-title"><div><h2>Datos de la cuenta</h2><p>El acceso se realiza por un enlace seguro enviado al correo.</p></div><Icon name="users" :size="19"/></div><div class="p-form-grid"><div class="p-field"><label for="user-name">Nombre <span class="required">*</span></label><input id="user-name" v-model.trim="form.name" required maxlength="100" autocomplete="name"/></div><div class="p-field"><label for="user-email">Correo electrónico <span class="required">*</span></label><input id="user-email" v-model.trim="form.email" required type="email" maxlength="254" autocomplete="email"/></div><div class="p-field"><label class="p-check"><input v-model="form.active" type="checkbox"/>Cuenta habilitada</label><small>Al desactivar se bloquea el acceso del vendedor.</small></div></div></section><section class="p-section-card"><div class="p-section-title"><div><h2>Plan y renovación</h2><p>Las renovaciones suman días desde el vencimiento vigente o desde hoy si ya venció.</p></div><Icon name="crown" :size="19"/></div><div v-if="user" class="p-info">Plan actual: <strong>{{plans.find(p=>p._id===idOf(user.planId))?.name||'Sin plan asignado'}}</strong> · Vence: <strong>{{shortDate(user.planExpiresAt)}}</strong><br/>Período de prueba hasta {{shortDate(user.trialEndsAt)}}.</div><div class="p-form-grid"><div class="p-field"><label for="assign-plan">Plan</label><select id="assign-plan" v-model="assignment.planId" @change="choosePlan"><option value="">Sin asignar</option><option v-for="plan in plans.filter(p=>p.active)" :key="plan._id" :value="plan._id">{{plan.name}}{{plan.visible===false?' · Oculto':''}}</option></select></div><div class="p-field"><label for="assign-days">Días a asignar</label><input id="assign-days" v-model.number="assignment.days" type="number" min="1" max="3650" step="1" :required="!!assignment.planId"/></div></div><div v-if="editing" class="p-form-actions"><button type="button" class="btn btn-secondary" :disabled="renewing||!assignment.planId" @click="renew"><Icon name="refresh" :size="15"/>{{renewing?'Guardando...':'Asignar / renovar plan'}}</button></div><p v-if="!plans.length" class="p-help">Creá un plan desde Configuración → Planes para poder asignarlo.</p></section><footer class="p-form-footer"><small>Los datos se guardan de forma segura.</small><div class="p-form-actions"><RouterLink to="/app/users" class="btn btn-secondary">Cancelar</RouterLink><button class="btn btn-primary" :disabled="saving">{{saving?'Guardando...':editing?'Guardar cambios':'Crear vendedor'}}</button></div></footer></form></div></template>
